local _K = {0x5A, 0x93, 0xC1, 0x47, 0xDE, 0x28, 0x7E, 0xB4, 0x19, 0x6F, 0x82, 0x3D, 0xA5, 0xE0, 0x12, 0xF9}
local _B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _D(data)
    local b64 = data:gsub("%s+", "")
    local dec = {}
    local lookup = {}
    for i = 1, #_B do lookup[_B:byte(i)] = i - 1 end
    local i = 1
    local len = #b64
    while i <= len do
        local c1 = lookup[b64:byte(i)] or 0
        local c2 = lookup[b64:byte(i+1)] or 0
        local c3 = lookup[b64:byte(i+2)]
        local c4 = lookup[b64:byte(i+3)]
        local b1 = (c1 * 4) + math.floor(c2 / 16)
        table.insert(dec, string.char(b1 % 256))
        if c3 ~= nil then
            local b2 = ((c2 % 16) * 16) + math.floor(c3 / 4)
            table.insert(dec, string.char(b2 % 256))
        end
        if c4 ~= nil then
            local b3 = ((c3 % 4) * 64) + c4
            table.insert(dec, string.char(b3 % 256))
        end
        i = i + 4
    end
    return table.concat(dec)
end

local _R = _D(_E)
local _O = {}
local _KL = #_K
for i = 1, #_R do
    local b = _R:byte(i)
    local k = _K[((i - 1) % _KL) + 1]
    local bit_xor = 0
    local p = 1
    local a, c = b, k
    for _ = 1, 8 do
        local ra, rc = a % 2, c % 2
        if ra ~= rc then bit_xor = bit_xor + p end
        a = math.floor(a / 2)
        c = math.floor(c / 2)
        p = p * 2
    end
    table.insert(_O, string.char(bit_xor))
end

local _S = table.concat(_O)
local fn, err = loadstring(_S)
if not fn then
    error("[MARVIN OBFUSCATION INTEGRITY ERROR] " .. tostring(err))
end
return fn()
